// Omniflow batch 296-310 — WORKSPACE TOOLS: duplicate merge + broadcast calendar
// + weekly summary, all in one delivery.
// Run from the folder that contains BOTH repos (Omniflow/ and OmniFlow-Control-Plane/):
//   node add_batch_296_310.mjs
// CP:  NEW portal_insights.py — GET /insights/weekly (7-day aggregates: new chats,
//      messages in/out by direction, cod.confirmed/declined + broadcast counts from
//      the action log, csat asked/avg, day-by-day chats+inbound rows) and
//      GET /insights/calendar?month=YYYY-MM (broadcasts positioned by
//      COALESCE(send_at, created_at), per-day sent vs queued counts from
//      materialized_at, body preview <=120; month regex-validated, defaults to the
//      current month). POST /customers/merge in portal_conversations.py — moves the
//      duplicate contact's conversations (404 when zero), stage rows (conflicting
//      row deleted first, table guarded via to_regclass), cod requests (guarded),
//      then audits customers.merged with the moved-chat count.
//      app.py registers portal_insights_bp on the portal_pipeline anchors.
// Web: portal.ts WeeklySummary/BroadcastCalendar/MergeMutation + getWeeklySummary /
//      getBroadcastCalendar / mergeCustomers clients; THREE BFF routes
//      (insights/weekly + insights/calendar + customers/merge, 6 ups each);
//      NEW /dashboard/weekly page (8 stat tiles incl. avg rating + a day-by-day
//      cyan/green bar list); NEW /dashboard/broadcasts/calendar page (month grid
//      with prev/next, sent/queued chips per day, month list below) linked from
//      the broadcasts header; customers page gets a per-row Merge dialog
//      (keep-select from loaded contacts, undo warning, refresh after merge);
//      sidebar "Weekly" item.
// Tests (rig, not this patcher): test_workspace_tools.py 67, test_workspace_tools_ui.py 54.
// Idempotent: re-run reports "already done" per block. Backups: *.pre_b296310.bak
import fs from "fs";
import { createRequire } from "module";
const require = createRequire(import.meta.url);

const BACKUP_TAG = ".pre_b296310.bak";
let applied = 0;
let already = 0;
let warnings = 0;

function compilePython(pathArg) {
  const { spawnSync } = require("child_process");
  for (const py of ["python3", "python", "py"]) {
    const probe = spawnSync(py, ["--version"], { encoding: "utf8" });
    if (probe.status !== 0) continue;
    const check = spawnSync(py, ["-c", "import sys;sys.exit(0 if sys.version_info[0]>=3 else 1)"], { encoding: "utf8" });
    if (check.status !== 0) continue;
    const result = spawnSync(py, ["-c", "import py_compile,sys;py_compile.compile(sys.argv[1],doraise=True);sys.exit(0)", pathArg], { encoding: "utf8" });
    return result.status === 0;
  }
  console.log("  (python not found — skipped compile guard)");
  return true;
}

function applySwaps(repoPath, marker, isCp, swaps) {
  if (!fs.existsSync(repoPath)) {
    console.log("SKIP (file not found): " + repoPath);
    warnings++;
    return;
  }
  const original = fs.readFileSync(repoPath, "utf8").replace(/\r\n/g, "\n");
  if (original.includes(marker)) {
    console.log("= " + repoPath + " (already patched)");
    already++;
    return;
  }
  const backup = repoPath + BACKUP_TAG;
  if (!fs.existsSync(backup)) fs.copyFileSync(repoPath, backup);
  let updated = original;
  let ok = true;
  for (const [frm, to] of swaps) {
    if (!updated.includes(frm)) {
      console.log("  ? " + repoPath + " :: anchor NOT FOUND — report this");
      ok = false;
      warnings++;
      break;
    }
    updated = updated.replace(frm, to);
  }
  if (!ok) return;
  fs.writeFileSync(repoPath, updated, "utf8");
  if (isCp && !compilePython(repoPath)) {
    fs.copyFileSync(backup, repoPath);
    console.log("FAIL (compile failed, restored): " + repoPath);
    warnings++;
    return;
  }
  console.log("+ " + repoPath + " (" + swaps.length + ")");
  applied++;
}

function writeNew(repoPath, marker, isCp, content) {
  if (!fs.existsSync(repoPath)) {
    fs.mkdirSync(repoPath.replace(/\/[^/]*$/, ""), { recursive: true });
    fs.writeFileSync(repoPath, content, "utf8");
    if (isCp && !compilePython(repoPath)) {
      console.log("FAIL (compile failed): " + repoPath);
      warnings++;
      return;
    }
    console.log("+ " + repoPath + " (new file)");
    applied++;
    return;
  }
  const original = fs.readFileSync(repoPath, "utf8").replace(/\r\n/g, "\n");
  if (original.includes(marker)) {
    console.log("= " + repoPath + " (already patched)");
    already++;
    return;
  }
  console.log("  ? " + repoPath + " exists WITHOUT marker — report this");
  warnings++;
}


writeNew("OmniFlow-Control-Plane/portal_insights.py", "portal_insights", true,
"\"\"\"Workspace insights: weekly summary and the broadcast calendar.\"\"\"\n\nimport logging\nimport re\nfrom datetime import datetime, timedelta, timezone\nfrom typing import Any, Dict, Optional, Tuple\n\nfrom flask import Blueprint, jsonify, request\n\nfrom portal_auth import (\n    PortalAuthUnavailable,\n    authenticate_portal_request,\n)\nimport portal_db\n\nbp = Blueprint(\"portal_insights\", __name__, url_prefix=\"/api/v1/portal\")\n\nlogger = logging.getLogger(__name__)\n\nWINDOW_DAYS = 7\nMONTH_RE = re.compile(r\"^\\d{4}-(0[1-9]|1[0-2])$\")\n\n\ndef _principal_or_error():\n    try:\n        principal = authenticate_portal_request()\n    except PortalAuthUnavailable as error:\n        return None, (jsonify({\"error\": {\"code\": \"portal_unavailable\",\n                                         \"message\": str(error)}}), 503)\n    if principal is None:\n        return None, (jsonify({\"error\": {\"code\": \"unauthorized\",\n                                         \"message\": \"Sign in required.\"}}), 401)\n    return principal, None\n\n\ndef _rows(cur, sql: str, params: tuple) -> list:\n    cur.execute(sql, params)\n    return portal_db.rows(cur)\n\n\ndef _day_key(when: Any) -> str:\n    \"\"\"YYYY-MM-DD from a datetime or an ISO string; blank when unknown.\"\"\"\n    if when is None:\n        return \"\"\n    if isinstance(when, str):\n        return when[:10]\n    try:\n        return when.strftime(\"%Y-%m-%d\")\n    except AttributeError:\n        return \"\"\n\n\n@bp.get(\"/insights/weekly\")\ndef weekly_summary():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    client_id = principal[\"client_id\"]\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                chats = _rows(\n                    cur,\n                    \"SELECT COUNT(*) AS total FROM \" + portal_db._q(portal_db.CONV_TABLE) +\n                    \" WHERE client_id = %s\"\n                    \" AND created_at >= NOW() - INTERVAL '\" + str(WINDOW_DAYS) + \" days'\",\n                    (client_id,),\n                )\n                messages = _rows(\n                    cur,\n                    \"SELECT m.direction, COUNT(*) AS total\"\n                    \" FROM \" + portal_db._q(portal_db.MSGS_TABLE) + \" m\"\n                    \" JOIN \" + portal_db._q(portal_db.CONV_TABLE) + \" c\"\n                    \" ON c.id = m.conversation_id\"\n                    \" WHERE c.client_id = %s\"\n                    \" AND m.created_at >= NOW() - INTERVAL '\" + str(WINDOW_DAYS) + \" days'\"\n                    \" GROUP BY m.direction\",\n                    (client_id,),\n                )\n                actions = _rows(\n                    cur,\n                    \"SELECT action, COUNT(*) AS total FROM \" +\n                    portal_db._q(\"portal_action_log\") +\n                    \" WHERE client_id = %s\"\n                    \" AND created_at >= NOW() - INTERVAL '\" + str(WINDOW_DAYS) + \" days'\"\n                    \" GROUP BY action\",\n                    (client_id,),\n                )\n                broadcasts = _rows(\n                    cur,\n                    \"SELECT COUNT(*) AS total FROM \" + portal_db._q(portal_db.BROADCASTS_TABLE) +\n                    \" WHERE client_id = %s\"\n                    \" AND created_at >= NOW() - INTERVAL '\" + str(WINDOW_DAYS) + \" days'\",\n                    (client_id,),\n                )\n                csat = _rows(\n                    cur,\n                    \"SELECT COUNT(*) AS asked, AVG(score) AS avg_score FROM \" +\n                    portal_db._q(portal_db.CSAT_TABLE) +\n                    \" WHERE client_id = %s\"\n                    \" AND requested_at >= NOW() - INTERVAL '\" + str(WINDOW_DAYS) + \" days'\",\n                    (client_id,),\n                )\n                daily_chats = _rows(\n                    cur,\n                    \"SELECT to_char(date_trunc('day', created_at), 'YYYY-MM-DD') AS day,\"\n                    \" COUNT(*) AS total\"\n                    \" FROM \" + portal_db._q(portal_db.CONV_TABLE) +\n                    \" WHERE client_id = %s\"\n                    \" AND created_at >= NOW() - INTERVAL '\" + str(WINDOW_DAYS) + \" days'\"\n                    \" GROUP BY 1 ORDER BY 1\",\n                    (client_id,),\n                )\n                daily_in = _rows(\n                    cur,\n                    \"SELECT to_char(date_trunc('day', m.created_at), 'YYYY-MM-DD') AS day,\"\n                    \" COUNT(*) AS total\"\n                    \" FROM \" + portal_db._q(portal_db.MSGS_TABLE) + \" m\"\n                    \" JOIN \" + portal_db._q(portal_db.CONV_TABLE) + \" c\"\n                    \" ON c.id = m.conversation_id\"\n                    \" WHERE c.client_id = %s AND m.direction = 'in'\"\n                    \" AND m.created_at >= NOW() - INTERVAL '\" + str(WINDOW_DAYS) + \" days'\"\n                    \" GROUP BY 1 ORDER BY 1\",\n                    (client_id,),\n                )\n        finally:\n            conn.close()\n    except Exception as error:\n        logger.warning(\"weekly summary failed: %s\", error)\n        return jsonify(portal_db.portal_unavailable(error, \"weekly summary\")[0]), 503\n\n    messages_in = messages_out = 0\n    for row in messages:\n        total = int(row.get(\"total\") or 0)\n        if row.get(\"direction\") == \"out\":\n            messages_out = total\n        else:\n            messages_in += total\n    action_map = {row.get(\"action\"): int(row.get(\"total\") or 0) for row in actions}\n    chat_map = {row.get(\"day\"): int(row.get(\"total\") or 0) for row in daily_chats}\n    in_map = {row.get(\"day\"): int(row.get(\"total\") or 0) for row in daily_in}\n\n    today = datetime.now(timezone.utc).date()\n    days = []\n    for offset in range(WINDOW_DAYS - 1, -1, -1):\n        day = (today - timedelta(days=offset)).isoformat()\n        days.append({\n            \"day\": day,\n            \"chats\": chat_map.get(day, 0),\n            \"inbound\": in_map.get(day, 0),\n        })\n\n    avg_score = None\n    if csat and csat[0].get(\"avg_score\") is not None:\n        try:\n            avg_score = round(float(csat[0][\"avg_score\"]), 1)\n        except (TypeError, ValueError):\n            avg_score = None\n    return jsonify({\n        \"chats\": int(chats[0].get(\"total\") or 0) if chats else 0,\n        \"messages_in\": messages_in,\n        \"messages_out\": messages_out,\n        \"cod_confirmed\": action_map.get(\"cod.confirmed\", 0),\n        \"cod_declined\": action_map.get(\"cod.declined\", 0),\n        \"broadcasts\": int(broadcasts[0].get(\"total\") or 0) if broadcasts else 0,\n        \"csat_asked\": int(csat[0].get(\"asked\") or 0) if csat else 0,\n        \"csat_avg\": avg_score,\n        \"days\": days,\n    }), 200\n\n\n@bp.get(\"/insights/calendar\")\ndef broadcast_calendar():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    month = (request.args.get(\"month\") or \"\").strip()\n    if not month:\n        month = datetime.now(timezone.utc).strftime(\"%Y-%m\")\n    if not MONTH_RE.match(month):\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"month must look like 2026-09.\"}}), 400\n    year, mon = int(month[:4]), int(month[5:7])\n    if year < 2020 or year > 2100:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"month is out of range.\"}}), 400\n    start = datetime(year, mon, 1, tzinfo=timezone.utc)\n    end = datetime(year + (mon == 12), (mon % 12) + 1, 1, tzinfo=timezone.utc)\n    client_id = principal[\"client_id\"]\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                rows = _rows(\n                    cur,\n                    \"SELECT id, audience, body, recipient_count,\"\n                    \" send_at, created_at, materialized_at\"\n                    \" FROM \" + portal_db._q(portal_db.BROADCASTS_TABLE) +\n                    \" WHERE client_id = %s\"\n                    \" AND COALESCE(send_at, created_at) >= %s\"\n                    \" AND COALESCE(send_at, created_at) < %s\"\n                    \" ORDER BY COALESCE(send_at, created_at), id\",\n                    (client_id, start, end),\n                )\n        finally:\n            conn.close()\n    except Exception as error:\n        logger.warning(\"broadcast calendar failed: %s\", error)\n        return jsonify(portal_db.portal_unavailable(error, \"broadcast calendar\")[0]), 503\n\n    day_map: Dict[str, Dict[str, int]] = {}\n    items = []\n    for row in rows:\n        when = row.get(\"send_at\") or row.get(\"created_at\")\n        day = _day_key(when)\n        scheduled = row.get(\"send_at\") is not None and row.get(\"materialized_at\") is None\n        bucket = day_map.setdefault(day, {\"sent\": 0, \"scheduled\": 0})\n        if scheduled:\n            bucket[\"scheduled\"] += 1\n        else:\n            bucket[\"sent\"] += 1\n        body = str(row.get(\"body\") or \"\")\n        items.append({\n            \"id\": row.get(\"id\"),\n            \"day\": day,\n            \"audience\": row.get(\"audience\") or \"all\",\n            \"body\": body[:120],\n            \"recipients\": int(row.get(\"recipient_count\") or 0),\n            \"scheduled\": scheduled,\n        })\n    days = [{\"date\": key, \"sent\": value[\"sent\"], \"scheduled\": value[\"scheduled\"]}\n            for key, value in sorted(day_map.items())]\n    return jsonify({\"month\": month, \"days\": days, \"items\": items}), 200\n");


