writeNew("Omniflow/app/api/omniflow/portal/insights/weekly/route.ts", "getWeeklySummary", false,
"import {\n  getWeeklySummary,\n  requirePortalAccessToken,\n} from \"../../../../../../lib/omniflow/portal\";\nimport {\n  noStoreHeaders,\n  safeJson,\n} from \"../../../../../../lib/omniflow/request-security\";\nimport { ControlPlaneRequestError } from \"../../../../../../lib/omniflow/control-plane\";\n\n\nexport async function GET() {\n  const accessToken = await requirePortalAccessToken();\n  if (!accessToken) {\n    return safeJson(\n      { error: { code: \"unauthorized\", message: \"Sign in required.\" } },\n      401\n    );\n  }\n\n  try {\n    const summary = await getWeeklySummary(accessToken);\n    if (summary === null) {\n      return safeJson(\n        { error: { code: \"not_found\", message: \"Summary unavailable.\" } },\n        404\n      );\n    }\n    return safeJson(summary, 200);\n  } catch (error) {\n    if (error instanceof ControlPlaneRequestError && error.isUnauthorized) {\n      return safeJson(\n        { error: { code: \"unauthorized\", message: \"Session expired.\" } },\n        401\n      );\n    }\n    return safeJson(\n      { error: { code: \"portal_unavailable\", message: \"Try again shortly.\" } },\n      503\n    );\n  }\n}\n");


writeNew("Omniflow/app/api/omniflow/portal/insights/calendar/route.ts", "getBroadcastCalendar", false,
"import {\n  getBroadcastCalendar,\n  requirePortalAccessToken,\n} from \"../../../../../../lib/omniflow/portal\";\nimport {\n  noStoreHeaders,\n  safeJson,\n} from \"../../../../../../lib/omniflow/request-security\";\nimport { ControlPlaneRequestError } from \"../../../../../../lib/omniflow/control-plane\";\n\nconst MONTH_RE = /^\\d{4}-(0[1-9]|1[0-2])$/;\n\n\nexport async function GET(request: Request) {\n  const accessToken = await requirePortalAccessToken();\n  if (!accessToken) {\n    return safeJson(\n      { error: { code: \"unauthorized\", message: \"Sign in required.\" } },\n      401\n    );\n  }\n\n  const month = (new URL(request.url).searchParams.get(\"month\") || \"\").trim();\n  if (month && !MONTH_RE.test(month)) {\n    return safeJson(\n      { error: { code: \"bad_request\", message: \"month must look like 2026-09.\" } },\n      400\n    );\n  }\n\n  try {\n    const calendar = await getBroadcastCalendar(accessToken, month);\n    if (calendar === null) {\n      return safeJson(\n        { error: { code: \"not_found\", message: \"Calendar unavailable.\" } },\n        404\n      );\n    }\n    return safeJson(calendar, 200);\n  } catch (error) {\n    if (error instanceof ControlPlaneRequestError && error.isUnauthorized) {\n      return safeJson(\n        { error: { code: \"unauthorized\", message: \"Session expired.\" } },\n        401\n      );\n    }\n    return safeJson(\n      { error: { code: \"portal_unavailable\", message: \"Try again shortly.\" } },\n      503\n    );\n  }\n}\n");


writeNew("Omniflow/app/api/omniflow/portal/customers/merge/route.ts", "mergeCustomers", false,
"import {\n  mergeCustomers,\n  requirePortalAccessToken,\n} from \"../../../../../../lib/omniflow/portal\";\nimport {\n  noStoreHeaders,\n  safeJson,\n} from \"../../../../../../lib/omniflow/request-security\";\nimport { ControlPlaneRequestError } from \"../../../../../../lib/omniflow/control-plane\";\n\n\nexport async function POST(request: Request) {\n  const accessToken = await requirePortalAccessToken();\n  if (!accessToken) {\n    return safeJson(\n      { error: { code: \"unauthorized\", message: \"Sign in required.\" } },\n      401\n    );\n  }\n\n  const payload: unknown = await request.json().catch(() => null);\n  const input =\n    payload !== null && typeof payload === \"object\"\n      ? (payload as Record<string, unknown>)\n      : {};\n  const keep = typeof input.keep === \"string\" ? input.keep.trim() : \"\";\n  const merge = typeof input.merge === \"string\" ? input.merge.trim() : \"\";\n  if (!keep || !merge || keep.length > 100 || merge.length > 100) {\n    return safeJson(\n      { error: { code: \"bad_request\", message: \"Both contacts are required.\" } },\n      400\n    );\n  }\n  if (keep === merge) {\n    return safeJson(\n      { error: { code: \"bad_request\", message: \"Pick two different contacts.\" } },\n      400\n    );\n  }\n\n  try {\n    const result = await mergeCustomers(accessToken, keep, merge);\n    if (result.kind === \"ok\") {\n      return safeJson({ ok: true, moved: result.moved }, 200);\n    }\n    if (result.kind === \"not_found\") {\n      return safeJson(\n        {\n          error: {\n            code: \"not_found\",\n            message: \"The duplicate contact has no chats.\",\n          },\n        },\n        404\n      );\n    }\n    return safeJson(\n      { error: { code: \"portal_unavailable\", message: \"Try again shortly.\" } },\n      503\n    );\n  } catch (error) {\n    if (error instanceof ControlPlaneRequestError && error.isUnauthorized) {\n      return safeJson(\n        { error: { code: \"unauthorized\", message: \"Session expired.\" } },\n        401\n      );\n    }\n    return safeJson(\n      { error: { code: \"portal_unavailable\", message: \"Try again shortly.\" } },\n      503\n    );\n  }\n}\n");


writeNew("Omniflow/app/dashboard/(portal)/weekly/page.tsx", "Weekly summary", false,
"\"use client\";\n\nimport { useCallback, useEffect, useState } from \"react\";\n\ninterface WeeklySummary {\n  chats: number;\n  messagesIn: number;\n  messagesOut: number;\n  codConfirmed: number;\n  codDeclined: number;\n  broadcasts: number;\n  csatAsked: number;\n  csatAvg: number | null;\n  days: { day: string; chats: number; inbound: number }[];\n}\n\nfunction dayLabel(iso: string): string {\n  const stamp = Date.parse(iso + \"T00:00:00Z\");\n  if (Number.isNaN(stamp)) return iso;\n  return new Intl.DateTimeFormat(\"en\", { weekday: \"short\" }).format(stamp);\n}\n\nexport default function WeeklyPage() {\n  const [summary, setSummary] = useState<WeeklySummary | null>(null);\n  const [failed, setFailed] = useState(false);\n\n  const load = useCallback(async () => {\n    setFailed(false);\n    try {\n      const response = await fetch(\"/api/omniflow/portal/insights/weekly\", {\n        credentials: \"same-origin\",\n        cache: \"no-store\",\n      });\n      if (!response.ok) {\n        setFailed(true);\n        return;\n      }\n      const payload = (await response.json().catch(() => null)) as {\n        chats?: number;\n        messages_in?: number;\n        messages_out?: number;\n        cod_confirmed?: number;\n        cod_declined?: number;\n        broadcasts?: number;\n        csat_asked?: number;\n        csat_avg?: number | null;\n        days?: { day?: string; chats?: number; inbound?: number }[];\n      } | null;\n      if (payload && typeof payload === \"object\" && Array.isArray(payload.days)) {\n        setSummary({\n          chats: payload.chats ?? 0,\n          messagesIn: payload.messages_in ?? 0,\n          messagesOut: payload.messages_out ?? 0,\n          codConfirmed: payload.cod_confirmed ?? 0,\n          codDeclined: payload.cod_declined ?? 0,\n          broadcasts: payload.broadcasts ?? 0,\n          csatAsked: payload.csat_asked ?? 0,\n          csatAvg:\n            typeof payload.csat_avg === \"number\" ? payload.csat_avg : null,\n          days: payload.days.map((day) => ({\n            day: typeof day.day === \"string\" ? day.day : \"\",\n            chats: typeof day.chats === \"number\" ? day.chats : 0,\n            inbound: typeof day.inbound === \"number\" ? day.inbound : 0,\n          })),\n        });\n      } else {\n        setFailed(true);\n      }\n    } catch {\n      setFailed(true);\n    }\n  }, []);\n\n  useEffect(() => {\n    void load();\n  }, [load]);\n\n  const peak = Math.max(\n    1,\n    ...(summary?.days ?? []).map((day) => Math.max(day.chats, day.inbound))\n  );\n\n  return (\n    <main className=\"min-h-screen bg-[#07111f] px-4 py-8 sm:px-6\">\n      <div className=\"mx-auto max-w-3xl\">\n        <p className=\"mb-1 text-[10px] font-medium uppercase tracking-[0.2em] text-cyan-400/70\">\n          Workspace\n        </p>\n        <h1 className=\"text-2xl font-semibold tracking-tight text-white\">\n          Weekly summary\n        </h1>\n        <p className=\"mt-1.5 text-sm text-slate-400\">\n          The last 7 days at a glance \u2014 chats, messages, orders and ratings.\n        </p>\n\n        {failed ? (\n          <p className=\"mt-6 text-sm text-slate-500\">\n            The summary is unavailable right now.\n          </p>\n        ) : summary === null ? (\n          <p className=\"mt-6 text-sm text-slate-500\">Loading\\\\u2026</p>\n        ) : (\n          <>\n            <div className=\"mt-5 grid grid-cols-2 gap-2 sm:grid-cols-4\">\n              {[\n                { label: \"New chats\", value: summary.chats },\n                { label: \"Messages in\", value: summary.messagesIn },\n                { label: \"Messages out\", value: summary.messagesOut },\n                { label: \"Broadcasts\", value: summary.broadcasts },\n                { label: \"COD confirmed\", value: summary.codConfirmed },\n                { label: \"COD declined\", value: summary.codDeclined },\n                { label: \"Ratings asked\", value: summary.csatAsked },\n                {\n                  label: \"Avg rating\",\n                  value: summary.csatAvg === null ? \"\\\\u2014\" : summary.csatAvg,\n                },\n              ].map((tile) => (\n                <div\n                  key={tile.label}\n                  className=\"rounded-2xl border border-white/[0.06] bg-white/[0.015] p-3 text-center\"\n                >\n                  <p className=\"text-xl font-semibold text-white\">{tile.value}</p>\n                  <p className=\"mt-0.5 text-[10px] uppercase tracking-wider text-slate-500\">\n                    {tile.label}\n                  </p>\n                </div>\n              ))}\n            </div>\n\n            <section className=\"mt-4 rounded-2xl border border-white/[0.06] bg-white/[0.015] p-4\">\n              <p className=\"text-xs font-semibold text-white\">Day by day</p>\n              <ul className=\"mt-3 space-y-2\">\n                {summary.days.map((day) => (\n                  <li key={day.day} className=\"flex items-center gap-3\">\n                    <span className=\"w-10 shrink-0 text-[11px] text-slate-500\">\n                      {dayLabel(day.day)}\n                    </span>\n                    <span className=\"flex-1\">\n                      <span className=\"flex h-2 items-center gap-0.5\">\n                        <span\n                          className=\"h-2 rounded-l bg-cyan-400/70\"\n                          style={{\n                            width: Math.round((day.inbound / peak) * 70) + \"%\",\n                          }}\n                        />\n                        <span\n                          className=\"h-2 rounded-r bg-emerald-400/60\"\n                          style={{\n                            width: Math.round((day.chats / peak) * 30) + \"%\",\n                          }}\n                        />\n                      </span>\n                    </span>\n                    <span className=\"w-24 shrink-0 text-right text-[11px] text-slate-500\">\n                      {day.inbound} in \\\\u00b7 {day.chats} chats\n                    </span>\n                  </li>\n                ))}\n              </ul>\n              <p className=\"mt-3 text-[10px] text-slate-600\">\n                Cyan = customer messages, green = new chats.\n              </p>\n            </section>\n          </>\n        )}\n      </div>\n    </main>\n  );\n}\n");


writeNew("Omniflow/app/dashboard/(portal)/broadcasts/calendar/page.tsx", "Broadcast calendar", false,
"\"use client\";\n\nimport { useCallback, useEffect, useState } from \"react\";\n\ninterface CalendarItem {\n  id: number;\n  day: string;\n  audience: string;\n  body: string;\n  recipients: number;\n  scheduled: boolean;\n}\n\ninterface CalendarData {\n  month: string;\n  days: { date: string; sent: number; scheduled: number }[];\n  items: CalendarItem[];\n}\n\nconst WEEKDAYS = [\"Mon\", \"Tue\", \"Wed\", \"Thu\", \"Fri\", \"Sat\", \"Sun\"];\n\nfunction shiftMonth(month: string, delta: number): string {\n  const [year, mon] = month.split(\"-\").map(Number);\n  const total = year * 12 + (mon - 1) + delta;\n  const nextYear = Math.floor(total / 12);\n  const nextMon = (total % 12) + 1;\n  return nextYear + \"-\" + String(nextMon).padStart(2, \"0\");\n}\n\nfunction monthTitle(month: string): string {\n  const stamp = Date.parse(month + \"-01T00:00:00Z\");\n  if (Number.isNaN(stamp)) return month;\n  return new Intl.DateTimeFormat(\"en\", {\n    month: \"long\",\n    year: \"numeric\",\n    timeZone: \"UTC\",\n  }).format(stamp);\n}\n\nfunction gridFor(month: string): (string | null)[] {\n  const first = Date.parse(month + \"-01T00:00:00Z\");\n  if (Number.isNaN(first)) return [];\n  const start = new Date(first);\n  const startWeekday = (start.getUTCDay() + 6) % 7;\n  const daysInMonth = new Date(\n    start.getUTCFullYear(),\n    start.getUTCMonth() + 1,\n    0\n  ).getUTCDate();\n  const cells: (string | null)[] = Array(startWeekday).fill(null);\n  for (let day = 1; day <= daysInMonth; day += 1) {\n    cells.push(month + \"-\" + String(day).padStart(2, \"0\"));\n  }\n  while (cells.length % 7 !== 0) cells.push(null);\n  return cells;\n}\n\nexport default function BroadcastCalendarPage() {\n  const [month, setMonth] = useState(() => new Date().toISOString().slice(0, 7));\n  const [data, setData] = useState<CalendarData | null>(null);\n  const [failed, setFailed] = useState(false);\n\n  const load = useCallback(async (target: string) => {\n    setFailed(false);\n    try {\n      const response = await fetch(\n        \"/api/omniflow/portal/insights/calendar?month=\" +\n          encodeURIComponent(target),\n        { credentials: \"same-origin\", cache: \"no-store\" }\n      );\n      if (!response.ok) {\n        setFailed(true);\n        setData(null);\n        return;\n      }\n      const payload = (await response.json().catch(() => null)) as\n        | (CalendarData & { items?: CalendarItem[] })\n        | null;\n      if (payload && typeof payload === \"object\" && Array.isArray(payload.items)) {\n        setData({\n          month: payload.month ?? target,\n          days: Array.isArray(payload.days) ? payload.days : [],\n          items: payload.items,\n        });\n      } else {\n        setFailed(true);\n        setData(null);\n      }\n    } catch {\n      setFailed(true);\n      setData(null);\n    }\n  }, []);\n\n  useEffect(() => {\n    void load(month);\n  }, [load, month]);\n\n  const byDay = new Map<string, { sent: number; scheduled: number }>();\n  for (const day of data?.days ?? []) byDay.set(day.date, day);\n\n  return (\n    <main className=\"min-h-screen bg-[#07111f] px-4 py-8 sm:px-6\">\n      <div className=\"mx-auto max-w-3xl\">\n        <div className=\"flex items-center justify-between gap-3\">\n          <div>\n            <h1 className=\"text-2xl font-semibold tracking-tight text-white\">\n              Broadcast calendar\n            </h1>\n            <p className=\"mt-1 text-sm text-slate-400\">\n              Sent and scheduled broadcasts by day.\n            </p>\n          </div>\n          <a\n            href=\"/dashboard/broadcasts\"\n            className=\"rounded-lg border border-white/[0.08] px-3 py-1.5 text-xs text-slate-400 transition hover:text-white\"\n          >\n            Back\n          </a>\n        </div>\n\n        <div className=\"mt-4 flex items-center justify-between gap-3\">\n          <button\n            type=\"button\"\n            onClick={() => setMonth((current) => shiftMonth(current, -1))}\n            className=\"rounded-lg border border-white/[0.08] px-3 py-1.5 text-xs text-slate-300 transition hover:text-white\"\n          >\n            \\\\u2190 Prev\n          </button>\n          <p className=\"text-sm font-medium text-white\">{monthTitle(month)}</p>\n          <button\n            type=\"button\"\n            onClick={() => setMonth((current) => shiftMonth(current, 1))}\n            className=\"rounded-lg border border-white/[0.08] px-3 py-1.5 text-xs text-slate-300 transition hover:text-white\"\n          >\n            Next \\\\u2192\n          </button>\n        </div>\n\n        {failed ? (\n          <p className=\"mt-6 text-sm text-slate-500\">\n            The calendar is unavailable right now.\n          </p>\n        ) : data === null ? (\n          <p className=\"mt-6 text-sm text-slate-500\">Loading\\\\u2026</p>\n        ) : (\n          <>\n            <div className=\"mt-4 grid grid-cols-7 gap-1 text-center\">\n              {WEEKDAYS.map((label) => (\n                <p key={label} className=\"pb-1 text-[10px] uppercase text-slate-600\">\n                  {label}\n                </p>\n              ))}\n              {gridFor(month).map((date, index) => {\n                if (date === null) {\n                  return <div key={\"pad\" + index} className=\"min-h-16\" />;\n                }\n                const entry = byDay.get(date);\n                const dayNumber = Number(date.slice(8, 10));\n                return (\n                  <div\n                    key={date}\n                    className=\"min-h-16 rounded-lg border border-white/[0.05] bg-white/[0.01] p-1\"\n                  >\n                    <p className=\"text-[10px] text-slate-600\">{dayNumber}</p>\n                    {entry && entry.sent > 0 ? (\n                      <p className=\"mt-0.5 rounded bg-emerald-400/10 px-0.5 text-[9px] text-emerald-300\">\n                        {entry.sent} sent\n                      </p>\n                    ) : null}\n                    {entry && entry.scheduled > 0 ? (\n                      <p className=\"mt-0.5 rounded bg-amber-400/10 px-0.5 text-[9px] text-amber-300\">\n                        {entry.scheduled} queued\n                      </p>\n                    ) : null}\n                  </div>\n                );\n              })}\n            </div>\n\n            {data.items.length > 0 ? (\n              <section className=\"mt-4 rounded-2xl border border-white/[0.06] bg-white/[0.015] p-4\">\n                <p className=\"text-xs font-semibold text-white\">This month</p>\n                <ul className=\"mt-2 space-y-1.5\">\n                  {data.items.map((item) => (\n                    <li\n                      key={item.id}\n                      className=\"flex items-center justify-between gap-2 text-xs\"\n                    >\n                      <span className=\"truncate text-slate-300\">\n                        {item.day.slice(8, 10)}\n                        {\" \\\\u00b7 \"}\n                        {item.body || \"(no text)\"}\n                      </span>\n                      <span\n                        className={\n                          \"shrink-0 \" +\n                          (item.scheduled ? \"text-amber-300\" : \"text-emerald-300\")\n                        }\n                      >\n                        {item.scheduled ? \"queued\" : \"sent\"} \\\\u00b7 {item.recipients}\n                      </span>\n                    </li>\n                  ))}\n                </ul>\n              </section>\n            ) : null}\n          </>\n        )}\n      </div>\n    </main>\n  );\n}\n");


